// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock provides the current time. time.Now satisfies this interface.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter is safe for use by multiple goroutines.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64
	maxBurst float64
	clock    Clock
}

// NewLimiter returns a Limiter that allows events at rate events per second
// with a maximum burst size of burst tokens. rate and burst must be > 0.
func NewLimiter(rate, burst float64) (*Limiter, error) {
	return NewLimiterWithClock(rate, burst, systemClock{})
}

// NewLimiterWithClock is like NewLimiter but uses the provided Clock,
// enabling deterministic testing.
func NewLimiterWithClock(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		tokens:   burst,
		last:     clock.Now(),
		rate:     rate,
		burst:    burst,
		maxBurst: burst,
		clock:    clock,
	}, nil
}

// Allow reports whether a single event may happen now.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n events may happen now.
// It consumes n tokens if enough are available; otherwise it consumes none.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.maxBurst {
			l.tokens = l.maxBurst
		}
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the number of tokens currently available.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
