package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock(t time.Time) *fakeClock { return &fakeClock{now: t} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewLimiterValidation(t *testing.T) {
	tests := []struct {
		name    string
		rate    float64
		burst   float64
		wantErr bool
	}{
		{"valid", 10, 5, false},
		{"zero rate", 0, 5, true},
		{"negative rate", -1, 5, true},
		{"zero burst", 10, 0, true},
		{"negative burst", 10, -1, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := NewLimiter(tc.rate, tc.burst)
			if (err != nil) != tc.wantErr {
				t.Fatalf("NewLimiter(%v, %v) err = %v, wantErr %v", tc.rate, tc.burst, err, tc.wantErr)
			}
		})
	}
}

func TestNewLimiterWithClockNil(t *testing.T) {
	if _, err := NewLimiterWithClock(1, 1, nil); err == nil {
		t.Fatal("expected error for nil clock")
	}
}

func TestAllowN(t *testing.T) {
	base := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)

	tests := []struct {
		name      string
		rate      float64
		burst     float64
		actions   []func(*Limiter, *fakeClock) bool
		want      []bool
		wantFinal float64
	}{
		{
			name:  "burst consumed immediately",
			rate:  1, burst: 3,
			actions: []func(*Limiter, *fakeClock) bool{
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(3) },
			},
			want:      []bool{true},
			wantFinal: 0,
		},
		{
			name:  "exceeds burst",
			rate:  1, burst: 2,
			actions: []func(*Limiter, *fakeClock) bool{
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(3) },
			},
			want:      []bool{false},
			wantFinal: 2,
		},
		{
			name:  "refill over time",
			rate:  1, burst: 2,
			actions: []func(*Limiter, *fakeClock) bool{
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(2) },
				func(l *Limiter, c *fakeClock) bool { c.Advance(2 * time.Second); return l.AllowN(1) },
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(1) },
			},
			want:      []bool{true, true, false},
			wantFinal: 1,
		},
		{
			name:  "tokens capped at burst",
			rate:  1, burst: 2,
			actions: []func(*Limiter, *fakeClock) bool{
				func(l *Limiter, c *fakeClock) bool { c.Advance(10 * time.Second); return l.AllowN(2) },
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(1) },
			},
			want:      []bool{true, false},
			wantFinal: 0,
		},
		{
			name:  "failed request consumes nothing",
			rate:  1, burst: 1,
			actions: []func(*Limiter, *fakeClock) bool{
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(2) },
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(1) },
			},
			want:      []bool{false, true},
			wantFinal: 0,
		},
		{
			name:  "non-positive n rejected",
			rate:  1, burst: 1,
			actions: []func(*Limiter, *fakeClock) bool{
				func(l *Limiter, _ *fakeClock) bool { return l.AllowN(0) },
			},
			want:      []bool{false},
			wantFinal: 1,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock(base)
			l, err := NewLimiterWithClock(tc.rate, tc.burst, clock)
			if err != nil {
				t.Fatalf("NewLimiterWithClock: %v", err)
			}
			for i, act := range tc.actions {
				if got := act(l, clock); got != tc.want[i] {
					t.Errorf("action %d: got %v, want %v", i, got, tc.want[i])
				}
			}
			if got := l.Tokens(); got != tc.wantFinal {
				t.Errorf("final tokens = %v, want %v", got, tc.wantFinal)
			}
		})
	}
}

func TestAllow(t *testing.T) {
	clock := newFakeClock(time.Time{})
	l, err := NewLimiterWithClock(10, 1, clock)
	if err != nil {
		t.Fatalf("NewLimiterWithClock: %v", err)
	}
	if !l.Allow() {
		t.Fatal("first Allow = false, want true")
	}
	if l.Allow() {
		t.Fatal("second Allow = true, want false")
	}
	clock.Advance(100 * time.Millisecond)
	if !l.Allow() {
		t.Fatal("Allow after refill = false, want true")
	}
}

func TestConcurrentAccess(t *testing.T) {
	clock := newFakeClock(time.Time{})
	l, err := NewLimiterWithClock(1000, 100, clock)
	if err != nil {
		t.Fatalf("NewLimiterWithClock: %v", err)
	}
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Errorf("allowed = %d, want 100 (burst fully available)", allowed)
	}
}
